def _tzdata_links() -> dict[str, str]:
    links: dict[str, str] = {}
    try:
        with open("/usr/share/zoneinfo/tzdata.zi", encoding="utf-8") as handle:
            for row in handle:
                fields = row.split()
                if len(fields) == 3 and fields[0] == "L":
                    links[fields[2]] = fields[1]
    except OSError:
        pass
    return links
''')
open(p,'w').write(s)
